    +'<circle cx="50" cy="50" r="'+r+'" fill="'+color+'" stroke="#fff" stroke-width="2.5"/>'
    +'<text x="50" y="46" text-anchor="middle" font-size="12" fill="#1e293b" font-weight="700">S/.</text>'
