  if(Math.random()<0.5){ const r=a*b+c; return {q:`${a} × ${b} + ${c} = ?`,a:r,opts:_sf6w4(r,(a+b)*c,a*b,a*b-c>0?a*b-c:a*b+c+1),mc:true}; }
