  if(Math.random()<0.5){ const r=(a+b)*c; return {q:`(${a} + ${b}) × ${c} = ?`,a:r,opts:_sf6w4(r,a*c+b,a+b*c,r+c),mc:true}; }
  const lo=Math.min(a,b),hi=Math.max(a,b),r=(hi-lo)*c;
