// ── UNIDAD: Polinomios — Grado Absoluto y Relativo ──────────────────────────
function _a6mkT(n){return Array.from({length:n},()=>({x:_a6rnd(2,9),y:_a6rnd(1,8),c:_a6rnd(2,5)}));}
