// ─── U1: Leyes de Exponentes I ───────────────────────────────────────────────
function _genI1A_EX1_B1(){
  var a=_i4grnd(2,8),b=_i4grnd(2,6),c=_i4grnd(1,4);
  var r1=1,r2=a*a*a,r3=b*b;
  return _i4gpick([
    // Plantilla 1: Definición de potencia
    {_id:1,q:'En la potencia 3⁵, ¿cuál es la base?',a:'3',opts:_i4gshuf(['3','5','15','35']),mc:true,ste:'En aᵇ, la base es a. En 3⁵, la base es 3 y el exponente es 5.'},
    {_id:2,q:'En la expresión 7⁴, ¿cuál es el exponente?',a:'4',opts:_i4gshuf(['4','7','28','3']),mc:true,ste:'En aᵇ, el exponente es b. En 7⁴, la base es 7 y el exponente es 4.'},
    {_id:3,q:'¿Cómo se llama el resultado de elevar una base a un exponente?',a:'Potencia',opts:_i4gshuf(['Potencia','Producto','Cociente','Raíz']),mc:true,ste:'En aᵇ = c, "c" recibe el nombre de potencia. La potencia es el resultado de la operación.'},
    {_id:4,q:'¿A qué es igual cualquier número distinto de cero elevado a la potencia cero?',a:'1',opts:_i4gshuf(['1','0','El mismo número','Indefinido']),mc:true,ste:'Propiedad: a⁰=1 para todo a≠0. Ej: 5⁰=1, (−7)⁰=1.'},
    // Plantilla 2: Cálculo con potencias positivas
    {_id:5,q:'Calcula: M = 2⁴ + 3² − 4⁰',a:'24',opts:_i4gshuf(['24','25','23','26']),mc:true,ste:'16 + 9 − 1 = 24.'},
    {_id:6,q:'Calcula: A = 6² − 5⁰ + 2³',a:'43',opts:_i4gshuf(['43','44','42','40']),mc:true,ste:'36−1+8 = 43.'},
    {_id:7,q:'Efectúa: E = 3³ − 2⁴ + 1¹⁰⁰',a:'12',opts:_i4gshuf(['12','10','14','11']),mc:true,ste:'27−16+1 = 12.'},
    {_id:8,q:'Calcula: B = 3³ + 4² − 5⁰',a:'42',opts:_i4gshuf(['42','43','41','40']),mc:true,ste:'27+16−1=42.'},
    // Plantilla 3: Potencias de bases negativas
    {_id:9,q:'Efectúa: P = (−3)² + (−2)³',a:'1',opts:_i4gshuf(['1','17','-1','5']),mc:true,ste:'9 + (−8) = 1.'},
    {_id:10,q:'Calcula: Q = (−4)² − (−3)³',a:'43',opts:_i4gshuf(['43','41','45','−11']),mc:true,ste:'(−4)²=16, (−3)³=−27. Q=16−(−27)=16+27=43.'},
    {_id:11,q:'Calcula: R = (−2)⁵ + (−3)²',a:'−23',opts:_i4gshuf(['−23','−41','−7','23']),mc:true,ste:'(−2)⁵=−32, (−3)²=9. R=−32+9=−23.'},
    {_id:12,q:'Calcula: S = (−5)² − (−2)³',a:'33',opts:_i4gshuf(['33','17','43','31']),mc:true,ste:'(−5)²=25, (−2)³=−8. S=25−(−8)=25+8=33.'},
    // Plantilla 4: Cálculos con suma y resta
    {_id:13,q:'Calcula: A = 2⁴ + (−3)² − 5⁰',a:'24',opts:_i4gshuf(['24','26','22','20']),mc:true,ste:'2⁴=16, (−3)²=9, 5⁰=1. 16+9−1=24.'},
    {_id:14,q:'Calcula: K = (−3)² + (−2)³ + 4⁰',a:'2',opts:_i4gshuf(['2','1','3','0']),mc:true,ste:'(−3)²=9, (−2)³=−8, 4⁰=1. 9−8+1=2.'},
    {_id:15,q:'Calcula: G = (−2)⁵ + 3³ + (−1)⁴',a:'−4',opts:_i4gshuf(['−4','−5','−3','4']),mc:true,ste:'(−2)⁵=−32, 3³=27, (−1)⁴=1. −32+27+1=−4.'},
    {_id:16,q:'Halla: Z = (−2)³ + 5² − 3¹',a:'14',opts:_i4gshuf(['14','12','16','18']),mc:true,ste:'(−2)³=−8, 5²=25, 3¹=3. −8+25−3=14.'},
    // Plantilla 5: Ecuaciones y razonamiento
    {_id:17,q:'¿Existe alguna diferencia entre evaluar −x³ y (−x)³ cuando x = 2?',a:'No, son iguales',opts:_i4gshuf(['No, son iguales','Sí, son distintos','Solo si x > 0','Depende del valor de x']),mc:true,ste:'−x³ = −(2³) = −8, y (−x)³ = (−2)³ = −8. Cuando el exponente es impar, −xⁿ = (−x)ⁿ porque el signo negativo no cambia.'},
    {_id:18,q:'¿Existe alguna diferencia entre evaluar −x² y (−x)² cuando x = 3?',a:'Sí, son distintos',opts:_i4gshuf(['Sí, son distintos','No, son iguales','Solo si x es negativo','Depende del exponente']),mc:true,ste:'−x² = −(3²) = −9, pero (−x)² = (−3)² = 9. Cuando el exponente es par, (−x)ⁿ = xⁿ pero −xⁿ = −(xⁿ). ¡Son opuestos!'},
    {_id:19,q:'¿A qué es igual cero elevado a la potencia cero?',a:'Indefinido',opts:_i4gshuf(['Indefinido','0','1','∞']),mc:true,ste:'0⁰ es una forma indeterminada — no tiene un valor definido universalmente.'},
    {_id:20,q:'¿Cuál es mayor: 2⁵ o 5²?',a:'2⁵',opts:_i4gshuf(['2⁵','5²','Son iguales','No se puede comparar']),mc:true,ste:'2⁵=32 y 5²=25. Por tanto 2⁵ > 5².'},
  ]);
}
