// ── Unidad 4: Polígonos (propiedades) ───────────────────────────────────────────

// ── B1 – Definición y clasificación ────────────────────────────────────────────
// P1(1-4):Definición | P2(5-8):Suma ángulos | P3(9-12):Regulares | P4(13-16):Cuadriláteros | P5(17-20):V/F
function _genSir1mPol_B1(){var sh=_i4gshuf;return _i4gpick([
  {_id:1,q:'¿Qué es un polígono?',a:'Figura plana cerrada formada por segmentos',opts:sh(['Figura plana cerrada formada por segmentos','Figura con lados curvos','Cualquier figura geométrica','Figura con exactamente 4 lados']),mc:true,ste:'Polígono: figura plana, cerrada y formada solo por segmentos rectilíneos.'},
  {_id:2,q:'Un polígono de 4 lados se llama...',a:'Cuadrilátero',opts:sh(['Cuadrilátero','Triángulo','Pentágono','Hexágono']),mc:true,ste:'Cuadri=4, látero=lados.'},
  {_id:3,q:'¿Cuántos lados tiene un hexágono?',a:'6',opts:sh(['6','5','7','8']),mc:true,ste:'Hexa=6.'},
  {_id:4,q:'Un polígono de 5 lados se llama...',a:'Pentágono',opts:sh(['Pentágono','Hexágono','Cuadrilátero','Heptágono']),mc:true,ste:'Penta=5.'},
  {_id:5,q:'¿Cuánto suman los ángulos interiores de un triángulo?',a:'180°',opts:sh(['180°','360°','90°','270°']),mc:true,ste:'Todo triángulo: suma de ángulos=180°.'},
  {_id:6,q:'¿Cuánto suman los ángulos interiores de un cuadrilátero?',a:'360°',opts:sh(['360°','180°','270°','540°']),mc:true,ste:'Cuadrilátero: (4−2)×180°=360°.'},
  {_id:7,q:'¿Cuánto suman los ángulos interiores de un pentágono?',a:'540°',opts:sh(['540°','360°','720°','450°']),mc:true,ste:'Pentágono: (5−2)×180°=540°.'},
  {_id:8,q:'La fórmula para la suma de ángulos interiores de un polígono de n lados es...',a:'(n−2)×180°',opts:sh(['(n−2)×180°','n×180°','(n−1)×180°','n×90°']),mc:true,ste:'S=(n−2)×180°.'},
  {_id:9,q:'Un polígono regular tiene todos sus lados y todos sus ángulos...',a:'Iguales entre sí',opts:sh(['Iguales entre sí','Solo los lados iguales','Solo los ángulos iguales','Ninguno de los anteriores']),mc:true,ste:'Polígono regular: lados iguales Y ángulos iguales.'},
  {_id:10,q:'¿Cómo se llama un polígono regular de 4 lados?',a:'Cuadrado',opts:sh(['Cuadrado','Rectángulo','Rombo','Trapecio']),mc:true,ste:'El cuadrado es el cuadrilátero regular.'},
  {_id:11,q:'En un hexágono regular, ¿cuánto mide cada ángulo interior?',a:'120°',opts:sh(['120°','90°','135°','60°']),mc:true,ste:'S=(6−2)×180°=720°. Cada ángulo=720°/6=120°.'},
  {_id:12,q:'En un octágono regular, ¿cuánto mide cada ángulo interior?',a:'135°',opts:sh(['135°','120°','90°','150°']),mc:true,ste:'S=(8−2)×180°=1080°. Cada ángulo=1080°/8=135°.'},
  {_id:13,q:'¿Cuál cuadrilátero tiene 2 pares de lados opuestos paralelos?',a:'Paralelogramo',opts:sh(['Paralelogramo','Trapecio','Trapecio isósceles','Deltoides']),mc:true,ste:'El paralelogramo tiene 2 pares de lados opuestos paralelos.'},
  {_id:14,q:'¿Qué cuadrilátero tiene exactamente UN par de lados paralelos?',a:'Trapecio',opts:sh(['Trapecio','Cuadrado','Rombo','Rectángulo']),mc:true,ste:'El trapecio tiene exactamente un par de lados paralelos.'},
  {_id:15,q:'V/F: "Todo cuadrado es un rectángulo."',a:'Verdadero',opts:sh(['Verdadero','Falso']),mc:true,ste:'Verdadero: el cuadrado cumple todas las propiedades del rectángulo.'},
  {_id:16,q:'V/F: "Todo rectángulo es un cuadrado."',a:'Falso',opts:sh(['Falso','Verdadero']),mc:true,ste:'Falso: un rectángulo no necesariamente tiene todos los lados iguales.'},
  {_id:17,q:'V/F: "Un rombo tiene todos sus lados iguales."',a:'Verdadero',opts:sh(['Verdadero','Falso']),mc:true,ste:'Verdadero: el rombo es un paralelogramo con los 4 lados iguales.'},
  {_id:18,q:'V/F: "Un rombo siempre tiene ángulos de 90°."',a:'Falso',opts:sh(['Falso','Verdadero']),mc:true,ste:'Falso: solo si el rombo tiene ángulos rectos es un cuadrado.'},
  {_id:19,q:'¿Cuántos ejes de simetría tiene un cuadrado?',a:'4',opts:sh(['4','2','1','8']),mc:true,ste:'El cuadrado tiene 4 ejes: 2 por los lados y 2 por las diagonales.'},
  {_id:20,q:'La suma de los ángulos exteriores de cualquier polígono convexo es...',a:'360°',opts:sh(['360°','180°','720°','540°']),mc:true,ste:'Siempre 360° para cualquier polígono convexo.'}
]);}
_SKILL_META['sir1m_pol_b1']={ico:'📐',lbl:'Definición y clasificación de polígonos',qCount:4,gen:_genSir1mPol_B1,plantillas:['Definición y elementos','Suma de ángulos interiores','Polígonos regulares','Clasificación de cuadriláteros','V/F combinados']};

// ── B2 – Propiedades de cuadriláteros ──────────────────────────────────────────
// P1(1-4):Rectángulo | P2(5-8):Rombo/cuadrado | P3(9-12):Paralelogramo | P4(13-16):Trapecio | P5(17-20):Relaciones V/F
function _genSir1mPol_B2(){var sh=_i4gshuf;return _i4gpick([
  {_id:1,q:'En un rectángulo, todos los ángulos son...',a:'90° (rectos)',opts:sh(['90° (rectos)','60°','45°','Todos diferentes']),mc:true,ste:'Por definición, el rectángulo tiene 4 ángulos rectos.'},
  {_id:2,q:'Las diagonales de un rectángulo son...',a:'Iguales y se bisecan',opts:sh(['Iguales y se bisecan','Perpendiculares','Distintas','Paralelas']),mc:true,ste:'En el rectángulo: AC=BD y se cortan en su punto medio.'},
  {_id:3,q:'Un rectángulo tiene largo 12 y ancho 5. ¿Cuánto mide su diagonal?',a:'13',opts:sh(['13','17','10','7']),mc:true,ste:'Pitágoras: d=√(144+25)=√169=13.'},
  {_id:4,q:'V/F: "En un rectángulo, los lados opuestos son paralelos e iguales."',a:'Verdadero',opts:sh(['Verdadero','Falso']),mc:true,ste:'Verdadero: el rectángulo es un paralelogramo.'},
  {_id:5,q:'En un rombo, los 4 lados son...',a:'Iguales',opts:sh(['Iguales','Paralelos','Perpendiculares','Diferentes']),mc:true,ste:'Definición: el rombo tiene los 4 lados congruentes.'},
  {_id:6,q:'Las diagonales del rombo son...',a:'Perpendiculares y se bisecan',opts:sh(['Perpendiculares y se bisecan','Iguales','Paralelas','Solo se bisecan']),mc:true,ste:'En el rombo: diagonales perpendiculares y se bisecan.'},
  {_id:7,q:'El cuadrado tiene...',a:'4 lados iguales y 4 ángulos de 90°',opts:sh(['4 lados iguales y 4 ángulos de 90°','Solo 4 lados iguales','Solo 4 ángulos de 90°','2 pares de lados paralelos distintos']),mc:true,ste:'El cuadrado combina rombo (lados iguales) y rectángulo (ángulos rectos).'},
  {_id:8,q:'V/F: "Todo cuadrado es un rombo."',a:'Verdadero',opts:sh(['Verdadero','Falso']),mc:true,ste:'Verdadero: el cuadrado tiene 4 lados iguales → es rombo con ángulos rectos.'},
  {_id:9,q:'En un paralelogramo, los ángulos opuestos son...',a:'Iguales',opts:sh(['Iguales','Suplementarios','Complementarios','Rectos']),mc:true,ste:'Propiedad: los ángulos opuestos de un paralelogramo son congruentes.'},
  {_id:10,q:'En un paralelogramo, los ángulos adyacentes son...',a:'Suplementarios (suman 180°)',opts:sh(['Suplementarios (suman 180°)','Iguales','Complementarios','Siempre 90°']),mc:true,ste:'Los ángulos adyacentes de un paralelogramo suman 180°.'},
  {_id:11,q:'En el paralelogramo ABCD, ∠A=70°. ¿Cuánto mide ∠B?',a:'110°',opts:sh(['110°','70°','90°','180°']),mc:true,ste:'∠A y ∠B son adyacentes (suplementarios): 180°−70°=110°.'},
  {_id:12,q:'Las diagonales del paralelogramo...',a:'Se bisecan mutuamente',opts:sh(['Se bisecan mutuamente','Son iguales','Son perpendiculares','No se cortan']),mc:true,ste:'En todo paralelogramo, las diagonales se bisecan.'},
  {_id:13,q:'El trapecio isósceles tiene los lados laterales...',a:'Iguales',opts:sh(['Iguales','Paralelos','Perpendiculares','Distintos']),mc:true,ste:'En el trapecio isósceles, los dos lados no paralelos son iguales.'},
  {_id:14,q:'En el trapecio rectángulo, uno de sus lados laterales es...',a:'Perpendicular a las bases',opts:sh(['Perpendicular a las bases','Igual a la otra lateral','Paralelo a las bases','Diagonal']),mc:true,ste:'Ese lado lateral coincide con la altura del trapecio.'},
  {_id:15,q:'V/F: "Un trapecio tiene dos pares de lados paralelos."',a:'Falso',opts:sh(['Falso','Verdadero']),mc:true,ste:'Falso: el trapecio tiene exactamente UN par de lados paralelos.'},
  {_id:16,q:'¿Cuánto suman los ángulos de la misma base en un trapecio?',a:'180°',opts:sh(['180°','90°','360°','Depende del tipo']),mc:true,ste:'Los ángulos co-interiores de un trapecio siempre suman 180°.'},
  {_id:17,q:'¿Cuál cuadrilátero tiene diagonales iguales Y perpendiculares?',a:'Cuadrado',opts:sh(['Cuadrado','Rombo','Rectángulo','Trapecio']),mc:true,ste:'El cuadrado: diagonales iguales (como rectángulo) y perpendiculares (como rombo).'},
  {_id:18,q:'V/F: "Todo paralelogramo es un trapecio."',a:'Verdadero',opts:sh(['Verdadero','Falso']),mc:true,ste:'Verdadero (definición inclusiva): el paralelogramo tiene 2 pares de lados paralelos → también cumple la condición del trapecio.'},
  {_id:19,q:'En el rombo ABCD, ∠A=60°. ¿Cuánto mide ∠B?',a:'120°',opts:sh(['120°','60°','90°','30°']),mc:true,ste:'El rombo es paralelogramo: ∠A y ∠B son adyacentes→180°−60°=120°.'},
  {_id:20,q:'V/F: "Las diagonales de un trapecio se bisecan mutuamente."',a:'Falso',opts:sh(['Falso','Verdadero']),mc:true,ste:'Falso: las diagonales del trapecio NO se bisecan. Solo las del paralelogramo sí.'}
]);}
