function _genSG3M_B5(){
  return _i4gpick([
  {_id:1,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(6))',a:'2',opts:_i4gshuf(['2','4','-3','6']),mc:true,ste:'g(6)=5. Luego f(g(6))=f(5)=2.'},
  {_id:2,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(-3))',a:'-3',opts:_i4gshuf(['-3','4','2','6']),mc:true,ste:'g(-3)=0. Luego f(g(-3))=f(0)=-3.'},
  {_id:3,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(-5))',a:'-5',opts:_i4gshuf(['-5','4','-3','2']),mc:true,ste:'g(-5)=3. Luego f(g(-5))=f(3)=-5.'},
  {_id:4,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(1))',a:'1',opts:_i4gshuf(['1','4','-3','2']),mc:true,ste:'g(1)=-4. Luego f(g(1))=f(-4)=1.'},
  {_id:5,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(2))',a:'-2',opts:_i4gshuf(['-2','5','0','3']),mc:true,ste:'f(2)=4. Luego g(f(2))=g(4)=-2.'},
  {_id:6,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(3))',a:'3',opts:_i4gshuf(['3','-2','5','0']),mc:true,ste:'f(3)=-5. Luego g(f(3))=g(-5)=3.'},
  {_id:7,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(-4))',a:'-4',opts:_i4gshuf(['-4','-2','5','0']),mc:true,ste:'f(-4)=1. Luego g(f(-4))=g(1)=-4.'},
  {_id:8,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(5))',a:'1',opts:_i4gshuf(['1','-2','5','0']),mc:true,ste:'f(5)=2. Luego g(f(5))=g(2)=1.'},
  {_id:9,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(6)) + g(f(2))',a:'0',opts:_i4gshuf(['0','4','1','-1']),mc:true,ste:'g(6)=5, f(g(6))=f(5)=2. f(2)=4, g(f(2))=g(4)=-2. Suma: 2+-2=0.'},
  {_id:10,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(-3)) + g(f(3))',a:'0',opts:_i4gshuf(['0','-6','1','-1']),mc:true,ste:'g(-3)=0, f(g(-3))=f(0)=-3. f(3)=-5, g(f(3))=g(-5)=3. Suma: -3+3=0.'},
  {_id:11,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(-5)) + g(f(-4))',a:'-9',opts:_i4gshuf(['-9','-1','-8','-10']),mc:true,ste:'g(-5)=3, f(g(-5))=f(3)=-5. f(-4)=1, g(f(-4))=g(1)=-4. Suma: -5+-4=-9.'},
  {_id:12,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle f(g(1)) + g(f(5))',a:'2',opts:_i4gshuf(['2','0','3','1']),mc:true,ste:'g(1)=-4, f(g(1))=f(-4)=1. f(5)=2, g(f(5))=g(2)=1. Suma: 1+1=2.'},
  {_id:13,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(2)) − f(g(6))',a:'-4',opts:_i4gshuf(['-4','0','-3','-5']),mc:true,ste:'f(2)=4, g(f(2))=g(4)=-2. g(6)=5, f(g(6))=f(5)=2. Resta: -2-(2)=-4.'},
  {_id:14,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(3)) − f(g(-3))',a:'6',opts:_i4gshuf(['6','0','7','5']),mc:true,ste:'f(3)=-5, g(f(3))=g(-5)=3. g(-3)=0, f(g(-3))=f(0)=-3. Resta: 3-(-3)=6.'},
  {_id:15,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(-4)) − f(g(-5))',a:'1',opts:_i4gshuf(['1','-9','2','0']),mc:true,ste:'f(-4)=1, g(f(-4))=g(1)=-4. g(-5)=3, f(g(-5))=f(3)=-5. Resta: -4-(-5)=1.'},
  {_id:16,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>halle g(f(5)) − f(g(1))',a:'0',opts:_i4gshuf(['0','2','1','-1']),mc:true,ste:'f(5)=2, g(f(5))=g(2)=1. g(1)=-4, f(g(1))=f(-4)=1. Resta: 1-(1)=0.'},
  {_id:17,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>¿cuál es el valor correcto de f(g(6))?',a:'2',opts:_i4gshuf(['2','4','-3','6']),mc:true,ste:'g(6)=5. Luego f(g(6))=f(5)=2.'},
  {_id:18,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>¿cuál es el valor correcto de f(g(-3))?',a:'-3',opts:_i4gshuf(['-3','4','2','6']),mc:true,ste:'g(-3)=0. Luego f(g(-3))=f(0)=-3.'},
  {_id:19,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>¿cuál es el valor correcto de f(g(-5))?',a:'-5',opts:_i4gshuf(['-5','4','-3','2']),mc:true,ste:'g(-5)=3. Luego f(g(-5))=f(3)=-5.'},
  {_id:20,q:'Dadas f = {(2, 4), (0, -3), (5, 2), (-1, 6), (3, -5), (-4, 1)}<br>g = {(4, -2), (6, 5), (-3, 0), (-5, 3), (2, 1), (-2, 4), (1, -4), (-4, 6)}<br>¿cuál es el valor correcto de f(g(1))?',a:'1',opts:_i4gshuf(['1','4','-3','2']),mc:true,ste:'g(1)=-4. Luego f(g(1))=f(-4)=1.'},
  ]);
}
