// ── Buscador global de unidades, habilidades y cursos (editorial/área) ─────
function _prepNorm(s) {
  return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
}
function _prepSearchUnits(query) {
  const q = _prepNorm(query).trim();
  if (q.length < 2) return [];
  const results = [];
  Object.entries(PREP_CURRICULUM).forEach(([level, gradeMap]) => {
    const lv = PREP_LEVELS[level] || {};
    if (lv._hidden) return; // no buscar en "Desafío de Dominio" (navegación distinta)
    Object.entries(gradeMap).forEach(([grade, units]) => {
      (units||[]).forEach((unit, idx) => {
        let matchReason = null;
        if (_prepNorm(unit.lbl).includes(q)) matchReason = { type:'unidad', text:unit.lbl };
        if (!matchReason) {
          for (const sk of (unit.skills||[])) {
            const meta = (typeof BINGO_TOPICS !== 'undefined' ? BINGO_TOPICS[sk] : null) || _SKILL_META[sk];
            if (meta && meta.lbl) {
              const cleanedLbl = (typeof _cleanLbl === 'function') ? _cleanLbl(meta.lbl, sk) : meta.lbl;
              if (_prepNorm(cleanedLbl).includes(q)) { matchReason = { type:'habilidad', text:cleanedLbl }; break; }
            }
          }
        }
        if (!matchReason) {
          // "Curso" = combinación editorial + área que se ve en el catálogo (ej. "Álgebra — Intelectum")
          const edInfo = unit.editorial ? PREP_EDITORIALS[unit.editorial] : null;
          const areaInfo = (lv.areas||[]).find(a=>a.key===unit.area);
          const edMatch = edInfo && (_prepNorm(edInfo.lbl).includes(q) || (edInfo.abbr && _prepNorm(edInfo.abbr).includes(q)));
          const areaMatch = areaInfo && _prepNorm(areaInfo.lbl).includes(q);
          if (edMatch || areaMatch) {
            const cursoTxt = (areaInfo ? areaInfo.lbl : '') + (areaInfo && edInfo ? ' — ' : '') + (edInfo ? edInfo.lbl : '');
            matchReason = { type:'curso', text: cursoTxt || (edInfo?edInfo.lbl:'') };
          }
        }
        if (matchReason) results.push({ level, grade, idx, unit, matchReason });
      });
    });
  });
  return results.slice(0, 40);
}
function _prepSearchResultsHtml(query) {
  const results = _prepSearchUnits(query);
  if (!results.length) return `<div style="padding:10px 12px;font-size:12px;color:rgba(255,255,255,0.35);text-align:center">Sin resultados para "${query}"</div>`;
  const rows = results.map(r => {
    const lv = PREP_LEVELS[r.level] || {};
    const ed = r.unit.editorial ? (PREP_EDITORIALS[r.unit.editorial]?.lbl || r.unit.editorial) : '';
    const areaInfo = (lv.areas||[]).find(a=>a.key===r.unit.area);
    const areaLbl = areaInfo ? areaInfo.lbl : (r.unit.area||'');
    const tag = [lv.lbl, r.grade+'°', ed, areaLbl].filter(Boolean).join(' · ');
    const matchTag = r.matchReason.type!=='unidad'
      ? `<div style="font-size:10.5px;color:#c084fc;margin-top:1px">${r.matchReason.type==='habilidad'?'Habilidad':'Curso'}: ${r.matchReason.text}</div>`
      : '';
    const lockIco = r.unit.locked ? '🔒 ' : '';
    return `<div class="prep-search-result" onclick="_prepSearchGoToUnit('${r.level}','${r.grade}',${r.idx})" style="padding:8px 10px;border-bottom:1px solid rgba(255,255,255,0.06);cursor:pointer;${r.unit.locked?'opacity:0.6;':''}" onmouseover="this.style.background='rgba(168,85,247,0.1)'" onmouseout="this.style.background='transparent'">
      <div style="font-size:13px;font-weight:700;color:#e2e8f0">${lockIco}${r.unit.lbl}</div>
      <div style="font-size:10.5px;color:rgba(255,255,255,0.4)">${tag}</div>
      ${matchTag}
    </div>`;
  }).join('');
  return `<div style="position:absolute;right:0;top:100%;margin-top:4px;width:300px;max-width:85vw;background:#0a0e1a;border:1px solid #1f2937;border-radius:12px;max-height:340px;overflow-y:auto;z-index:30;box-shadow:0 8px 24px rgba(0,0,0,0.5)">${rows}</div>`;
}
