function _genDsDiv1(){const n2=_dsRi(1,12),cociente=_dsRi(1,12),n1=n2*cociente;return{algo:'div',n1,n2,cociente,residuo:0,a:cociente+'r0',q:`${n1} ÷ ${n2}`};}
