function _genDsDiv3(){const n2=_dsRi(13,99),n1=_dsRi(10000,99999),cociente=Math.floor(n1/n2),residuo=n1%n2;return{algo:'div',n1,n2,cociente,residuo,a:cociente+'r'+residuo,q:`${n1} ÷ ${n2}`};}
