function _genDsComb3(){const a=_dsRi(10,50),b=_dsRi(2,9),c=_dsRi(10,50),d=_dsRi(2,9);return{algo:'comb',tokens:[a,'×',b,'+',c,'×',d],a:String(a*b+c*d),q:`${a} × ${b} + ${c} × ${d}`};}
