function _genDsComb12(){const sqs=[4,9,16,25,36,49,64,81,100],sq=sqs[_dsRi(0,sqs.length-1)],r=Math.sqrt(sq),a=r+_dsRi(1,15);return{algo:'comb',tokens:[a,'-',1,'√',sq],a:String(a-r),q:`${a} − √${sq}`};}
