async function loadPrepHistory() {
  _prepHistoryLoading = true;
  try {
    // uid: admin → 'teacher', loggeado → String(id), invitado → _bingoGuestUid
    const uid = isAdmin() ? 'teacher' : (getLoggedId() !== null ? String(getLoggedId()) : (_bingoGuestUid || null));
    if (!uid) { _prepHistoryData = []; _prepHistoryLoading = false; if (dashGamingMode==='preparate'||document.getElementById('preparate-pane')) _renderPreparatePane(); return; }
    const snap = await db.collection('prepHistory').where('uid','==',uid).limit(200).get();
    _prepHistoryData = [];
    snap.forEach(doc => _prepHistoryData.push({ id:doc.id, ...doc.data() }));
    // Ordenar por fecha desc en cliente (evita índice compuesto)
    _prepHistoryData.sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  } catch(e) { _prepHistoryData = []; console.error('prep history load', e); }
  _prepHistoryLoading = false;
  // Auto-abrir "Mis Cursos" si el alumno no tiene curso seleccionado y tiene cursos asignados
  if (!isAdmin() && !_prep.level && !_prep.openSelector) {
    const _lid = getLoggedId();
    if (_lid !== null && _lid !== 0 && _prepMyCourses(_lid).length > 0) {
      _prep.openSelector = 'miscursos';
    }
  }
  if (dashGamingMode==='preparate' || document.getElementById('preparate-pane')) _renderPreparatePane();
}
async function loadPrepHistoryAdmin() {
  if (!isAdmin()) return;
  _prepAdminHistLoading = true;
  try {
    // IMPORTANTE: antes este .limit(200) no tenía .orderBy(), así que Firestore devolvía 200
    // documentos "cualesquiera" de TODA la colección (de todos los alumnos, sin importar fecha) y
    // recién después se ordenaban en el cliente — para entonces ya se habían descartado al azar
    // sesiones recientes. Con .orderBy() antes del .limit(), Firestore trae directo las 200 más
    // recientes de verdad. (No requiere índice compuesto: no hay filtro where, solo orderBy.)
    const snap = await db.collection('prepHistory').orderBy('completedAt','desc').limit(200).get();
    _prepAdminHistData = [];
    snap.forEach(doc => _prepAdminHistData.push({ id:doc.id, ...doc.data() }));
    _prepAdminHistData.sort((a,b)=>(b.completedAt?.seconds||0)-(a.completedAt?.seconds||0));
  } catch(e) { _prepAdminHistData = []; console.error('prep admin history load', e); }
  _prepAdminHistLoading = false;
  _renderPreparatePane();
}
